    readonly kind: "node-global";
    readonly identity: `node:global@${number}#${string}`;
    readonly major: number;
    readonly realm: string;
};

export interface TemporalDefinition<Shape extends StateShape, Actions extends Readonly<Record<string, Update<StateOf<Shape>>>>> {
    readonly state: Shape;
    readonly init: StateOf<Shape>;
    readonly actions: Actions;
    readonly guards?: Partial<{
        readonly [Name in keyof Actions]: Predicate<StateOf<Shape>>;
    }>;
    readonly fairness?: Partial<{
        readonly [Name in keyof Actions]: "weak" | "strong";
    }>;
    readonly invariants?: Readonly<Record<string, Predicate<StateOf<Shape>>>>;
    readonly eventually?: Readonly<Record<string, Predicate<StateOf<Shape>>>>;
    readonly repeatedly?: Readonly<Record<string, Predicate<StateOf<Shape>>>>;
    readonly stabilizes?: Readonly<Record<string, Predicate<StateOf<Shape>>>>;
    readonly responses?: Readonly<Record<string, {
        readonly trigger: Predicate<StateOf<Shape>>;
        readonly response: Predicate<StateOf<Shape>>;
    }>>;
}

export interface TemporalType<Value> {
    readonly [temporalDescriptor]: Value;
    readonly kind: "int" | "nat" | "float" | "bool" | "string";
}
